*{box-sizing:border-box} :root{--ink:#071318;--panel:#0e2025;--line:rgba(196,225,220,.12);--acid:#d5ff40;--cream:#eef1df;--orange:#ff7a36}body{margin:0;font-family:'DM Sans',sans-serif;color:var(--cream);background:#08171b;min-height:100vh;overflow-x:hidden}.stadium{position:fixed;inset:0;z-index:-2;background:linear-gradient(180deg,rgba(5,15,19,.18),rgba(5,15,19,.78)),radial-gradient(ellipse at 70% 20%,rgba(173,255,220,.12),transparent 25%),linear-gradient(150deg,#10262b 0 50%,#09171b 50%)}.stadium:before{content:"";position:absolute;left:-5%;right:-5%;bottom:-28%;height:70%;border-radius:50% 50% 0 0;background:repeating-linear-gradient(90deg,rgba(255,255,255,.025) 0 2px,transparent 2px 48px),linear-gradient(155deg,#143a30,#09241e);box-shadow:0 -20px 60px rgba(180,255,221,.09)}.stadium-lights{position:absolute;width:100%;height:100%;background:radial-gradient(circle at 12% 8%,rgba(200,255,233,.3),transparent 10%),radial-gradient(circle at 88% 8%,rgba(200,255,233,.3),transparent 10%)}.crowd{position:absolute;bottom:28%;left:-10%;width:120%;height:18%;opacity:.18;background:radial-gradient(circle,#fff 0 1px,transparent 2px) 0 0/8px 8px}.app-shell{min-height:100vh}.topbar{height:76px;padding:0 28px;display:flex;align-items:center;border-bottom:1px solid var(--line);background:rgba(6,18,21,.88);backdrop-filter:blur(18px);position:relative;z-index:20}.brand{width:260px;display:flex;align-items:center;color:var(--cream);text-decoration:none}.brand-mark{font-family:'Barlow Condensed';font-size:34px;font-weight:900;line-height:1;color:#071318;background:var(--acid);height:44px;width:55px;display:grid;place-items:center;transform:skew(-8deg);border-radius:3px}.brand-copy{display:flex;flex-direction:column;margin-left:11px}.brand-copy b{font-family:'Barlow Condensed';font-size:20px;letter-spacing:1.5px}.brand-copy small{font-size:8px;letter-spacing:2.4px;color:#91aaa6}.top-center{flex:1;text-align:center;font-family:'Barlow Condensed';font-weight:700;font-size:13px;letter-spacing:1.8px;color:#a7bbb7}.live-dot,.online-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 12px var(--acid);margin-right:7px}.top-divider{margin:0 12px;color:#536864}.wallet{height:48px;min-width:150px;border-left:1px solid var(--line);display:flex;align-items:center;justify-content:flex-end;gap:9px}.wallet .coin{width:31px;height:31px;border-radius:50%;background:linear-gradient(135deg,#f4f7a2,#a2b54a);color:#263318;display:grid;place-items:center;font-weight:900;box-shadow:0 0 18px rgba(213,255,64,.18)}.wallet>span:nth-child(2){display:flex;flex-direction:column}.wallet small{font-size:8px;color:#829b97;letter-spacing:1.2px}.wallet strong{font-family:'Barlow Condensed';font-size:27px;line-height:25px}.wallet em{font-family:'Barlow Condensed';font-style:normal;font-size:12px;color:var(--acid);align-self:flex-end;margin-bottom:8px}.menu-toggle{display:none}.layout{height:calc(100vh - 76px);display:flex}.sidebar{width:260px;flex:none;border-right:1px solid var(--line);background:rgba(7,20,23,.72);padding:24px 18px 16px;display:flex;flex-direction:column}.side-label{font-family:'Barlow Condensed';font-size:10px;letter-spacing:2.2px;color:#718b87;margin:0 10px 12px}.main-nav{display:flex;flex-direction:column;gap:4px}.nav-item{height:48px;border:0;border-radius:4px;background:transparent;color:#91a7a3;text-align:left;padding:0 12px;font-family:'DM Sans';font-size:13px;font-weight:700;display:flex;align-items:center;gap:11px;cursor:pointer;transition:.18s}.nav-item:hover{background:rgba(255,255,255,.04);color:white}.nav-item.active{background:rgba(213,255,64,.1);color:var(--acid);box-shadow:inset 3px 0 var(--acid)}.nav-icon{width:24px;height:24px;border:1px solid currentColor;border-radius:50%;display:grid;place-items:center;font-size:12px}.nav-arrow,.nav-count{margin-left:auto;font-size:11px}.nav-count{border:1px solid var(--line);border-radius:20px;padding:3px 7px}.side-bottom{margin-top:auto}.event-card{height:64px;border:1px solid var(--line);background:rgba(255,255,255,.025);border-radius:5px;display:flex;align-items:center;padding:8px 10px}.event-icon{font-size:25px;margin-right:8px}.event-card div:nth-child(2){display:flex;flex-direction:column}.event-card b{font-family:'Barlow Condensed';font-size:13px}.event-card small{font-size:8px;color:#829a96;margin-top:3px}.event-arrow{margin-left:auto}.side-foot{height:42px;display:flex;align-items:flex-end;font-size:8px;letter-spacing:1.2px;color:#66807b}.main-content{flex:1;min-width:0;overflow:auto;position:relative}.view{display:none;min-height:100%;padding:34px 42px}.view.active{display:block}.mobile-nav{display:none}
.hero{height:100%;min-height:560px;display:grid;grid-template-columns:minmax(390px,1fr) minmax(430px,.75fr);align-items:center;gap:20px}.hero-copy{max-width:610px}.eyebrow{display:flex;align-items:center;gap:9px;font-family:'Barlow Condensed';font-weight:700;font-size:11px;letter-spacing:2.5px;color:var(--acid)}.eyebrow:before{content:"";width:34px;height:2px;background:var(--acid)}h1{font-family:'Barlow Condensed';font-size:clamp(64px,7vw,108px);line-height:.82;letter-spacing:-3px;margin:18px 0 24px;text-transform:uppercase}.hollow{-webkit-text-stroke:1.5px var(--cream);color:transparent}.hero-copy p{max-width:500px;color:#9eb1ad;line-height:1.7;font-size:14px}.hero-actions{display:flex;gap:12px;margin-top:28px}.primary-btn,.secondary-btn{height:58px;border:0;border-radius:3px;padding:0 25px;font-family:'Barlow Condensed';font-size:17px;font-weight:800;letter-spacing:1px;cursor:pointer;text-transform:uppercase}.primary-btn{background:var(--acid);color:#101a14;box-shadow:0 12px 32px rgba(213,255,64,.12)}.primary-btn:hover{transform:translateY(-2px)}.secondary-btn{border:1px solid var(--line);background:rgba(255,255,255,.04);color:white}.pack-stage{height:min(620px,70vh);min-height:480px;position:relative;display:grid;place-items:center}.pack-aura{position:absolute;width:80%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,rgba(213,255,64,.13),transparent 62%);animation:pulse 3s ease-in-out infinite}.pack-shadow{position:absolute;width:330px;height:40px;bottom:55px;border-radius:50%;background:rgba(0,0,0,.55);filter:blur(12px)}.pack{width:310px;height:430px;border-radius:12px;background:linear-gradient(145deg,#173c3f,#09191d);border:1px solid rgba(221,255,224,.23);box-shadow:0 30px 70px rgba(0,0,0,.55),inset 0 0 50px rgba(213,255,64,.04);position:relative;transform:rotate(2deg);transition:.35s;overflow:hidden}.pack:hover{transform:rotate(-1deg) translateY(-8px)}.pack:before{content:"";position:absolute;top:-20px;left:-10%;width:120%;height:50px;background:repeating-linear-gradient(135deg,rgba(213,255,64,.22) 0 2px,transparent 2px 8px),#0c2528;transform:rotate(-2deg)}.pack-grid{position:absolute;inset:50px 20px 40px;border:1px solid rgba(213,255,64,.25);clip-path:polygon(0 12%,50% 0,100% 12%,100% 88%,50% 100%,0 88%)}.pack-badge{position:absolute;top:75px;left:0;width:100%;text-align:center}.pack-badge strong{display:block;font-family:'Barlow Condensed';font-size:58px;line-height:.8}.pack-badge small{display:block;color:var(--acid);letter-spacing:5px;font-weight:800;font-size:10px;margin-top:12px}.pack-ball{position:absolute;width:155px;height:155px;border-radius:50%;bottom:70px;left:77px;border:10px solid rgba(238,241,223,.9);background:radial-gradient(circle at 35% 30%,#fff 0 3px,transparent 4px),repeating-conic-gradient(from 20deg,#0d2022 0 10deg,transparent 10deg 35deg);opacity:.95;box-shadow:0 15px 30px rgba(0,0,0,.28)}.pack-footer{position:absolute;bottom:18px;left:20px;right:20px;display:flex;justify-content:space-between;font-family:'Barlow Condensed';font-size:10px;letter-spacing:1.5px}.pack-footer b{color:var(--acid)}
.page-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:24px}.page-head h2{font-family:'Barlow Condensed';font-size:52px;text-transform:uppercase;margin:5px 0 0}.page-head p{color:#8fa39f;font-size:12px}.page-head .progress{width:220px}.progress-label{display:flex;justify-content:space-between;font-size:10px;margin-bottom:7px}.progress-track{height:5px;background:rgba(255,255,255,.08);border-radius:5px;overflow:hidden}.progress-fill{height:100%;background:var(--acid);box-shadow:0 0 12px var(--acid)}.team-grid,.card-grid,.shop-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px}.team-card,.shop-card{background:rgba(11,31,34,.88);border:1px solid var(--line);border-radius:7px;padding:16px;cursor:pointer;transition:.18s}.team-card:hover,.shop-card:hover{transform:translateY(-3px);border-color:rgba(213,255,64,.45)}.team-flag{height:52px;border-radius:4px;display:grid;place-items:center;font-family:'Barlow Condensed';font-size:27px;font-weight:900;background:linear-gradient(135deg,rgba(255,255,255,.13),rgba(255,255,255,.03))}.team-card h3{font-family:'Barlow Condensed';font-size:20px;margin:12px 0 4px}.team-card small{color:#839a96}.team-card .mini-progress{height:3px;background:rgba(255,255,255,.08);margin-top:12px}.team-card .mini-progress i{height:100%;display:block;background:var(--acid)}
.cards-page,.album-team-page{max-width:1100px;margin:auto}.card-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}.card{aspect-ratio:.72;position:relative;border-radius:9px;overflow:hidden;padding:8px;border:1px solid rgba(255,255,255,.25);box-shadow:0 12px 28px rgba(0,0,0,.28);transition:.25s;isolation:isolate}.card:hover{transform:translateY(-5px) rotate(1deg)}.card-bg{position:absolute;inset:0;background:linear-gradient(145deg,var(--card-a),var(--card-b));z-index:-2}.card-bg:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 70% 20%,rgba(255,255,255,.22),transparent 18%),repeating-linear-gradient(135deg,transparent 0 12px,rgba(255,255,255,.025) 12px 13px)}.rarity{font-family:'Barlow Condensed';font-size:9px;letter-spacing:1.4px;font-weight:800;text-transform:uppercase}.card-team{position:absolute;right:8px;top:8px;font-size:9px;background:rgba(0,0,0,.28);padding:3px 5px;border-radius:3px}.avatar{position:absolute;left:50%;top:22%;width:78%;height:48%;transform:translateX(-50%);border-radius:48% 48% 20% 20%;background:linear-gradient(145deg,rgba(255,255,255,.22),rgba(0,0,0,.18));border:2px solid rgba(255,255,255,.22);display:flex;align-items:flex-end;justify-content:center}.avatar:before{content:"";position:absolute;top:12%;width:35%;aspect-ratio:.82;border-radius:50%;background:var(--skin,#d69a78);box-shadow:0 28px 0 18px var(--shirt,#194f70)}.avatar:after{content:"";position:absolute;top:5%;width:38%;height:13%;border-radius:60% 60% 30% 30%;background:#202020}.card-name{position:absolute;bottom:20px;left:8px;right:8px;text-align:center;font-family:'Barlow Condensed';font-size:20px;font-weight:900;text-transform:uppercase;line-height:.9}.card-name small{display:block;font-size:8px;margin-top:5px;letter-spacing:1.5px}.card-count{position:absolute;bottom:5px;right:7px;font-size:9px;background:rgba(0,0,0,.45);border-radius:10px;padding:2px 6px}.card.locked{filter:grayscale(.85);opacity:.48}.card.locked .avatar,.card.locked .card-name{visibility:hidden}.card.locked:after{content:"?";position:absolute;inset:0;display:grid;place-items:center;font-size:60px;font-family:'Barlow Condensed';color:white}
.card.common{--card-a:#66746f;--card-b:#252f2d}.card.rare{--card-a:#4da6a1;--card-b:#153d42}.card.super-rare{--card-a:#4e79d0;--card-b:#18264e}.card.epic{--card-a:#9b57cf;--card-b:#3d1b56}.card.legendary{--card-a:#c19a32;--card-b:#59421a}.card.iconic{--card-a:#ee6448;--card-b:#762a38}.card.golden-baller{--card-a:#ffd85c;--card-b:#9a6516}.card.limited-edition{--card-a:#f6f1cb;--card-b:#0b8d80}.golden,.limited-edition{box-shadow:0 0 22px rgba(255,216,92,.55);animation:shine 2.5s linear infinite}.limited-edition:before{content:"";position:absolute;inset:-50%;background:linear-gradient(110deg,transparent 35%,rgba(255,255,255,.45) 48%,transparent 60%);animation:sweep 2.2s linear infinite;z-index:4}.rarity.legendary{color:#ffe56d}.rarity.iconic{color:#ff9277}.rarity.limited-edition{color:#fff9be}
.shop-card{min-height:230px;text-align:center;position:relative}.shop-card.featured{border-color:rgba(213,255,64,.5);background:linear-gradient(145deg,rgba(213,255,64,.08),rgba(11,31,34,.88))}.shop-pack{width:100px;height:140px;margin:10px auto 14px;border-radius:7px;background:linear-gradient(145deg,var(--pack-a,#315451),var(--pack-b,#0b2425));border:1px solid rgba(255,255,255,.22);display:grid;place-items:center;font-family:'Barlow Condensed';font-size:36px;font-weight:900;box-shadow:0 15px 25px rgba(0,0,0,.32);transform:rotate(-3deg)}.shop-card h3{font-family:'Barlow Condensed';font-size:23px;margin:5px}.shop-card p{font-size:10px;color:#829a96}.shop-card .buy-btn{width:100%;height:42px;margin-top:10px;border:0;border-radius:3px;background:var(--acid);font-weight:800;color:#102014;cursor:pointer}.shop-card.special .shop-pack{background:linear-gradient(145deg,#70488c,#241344)}
.modal-backdrop{position:fixed;inset:0;background:rgba(3,10,12,.86);backdrop-filter:blur(10px);z-index:100;display:none;place-items:center}.modal-backdrop.open{display:grid}.modal{width:min(94vw,1120px);max-height:88vh;overflow:hidden}.reveal-head{text-align:center;height:42px;font-family:'Barlow Condensed';font-size:16px;letter-spacing:3px;color:var(--acid)}.reveal-grid{display:grid;grid-template-columns:repeat(7,minmax(105px,1fr));gap:10px}.reveal-grid .card{height:300px;animation:deal .55s cubic-stats backwards}.reveal-grid .card:nth-child(2){animation-delay:.08s}.reveal-grid .card:nth-child(3){animation-delay:.16s}.reveal-grid .card:nth-child(4){animation-delay:.24s}.reveal-grid .card:nth-child(5){animation-delay:.32s}.reveal-grid .card:nth-child(6){animation-delay:.40s}.reveal-grid .card:nth-child(7){animation-delay:.48s}.modal-actions{display:flex;justify-content:center;gap:10px;margin-top:18px}.burst{position:fixed;z-index:200;pointer-events:none}.burst i{position:absolute;width:5px;height:5px;border-radius:50%;background:var(--acid);animation:burst 1.2s ease-out forwards}.toast{position:fixed;z-index:300;bottom:28px;left:50%;transform:translate(-50%,30px);padding:12px 18px;border-radius:4px;background:#dffb54;color:#102014;font-size:12px;font-weight:800;opacity:0;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}
.sell-row{display:grid;grid-template-columns:70px 1fr 120px 100px;align-items:center;gap:12px;padding:8px;border-bottom:1px solid var(--line)}.sell-row .mini-card{height:76px;border-radius:5px}.sell-row h3{font-family:'Barlow Condensed';font-size:18px;margin:0}.sell-row p{font-size:10px;color:#879a96}.sell-row button{height:38px;border:1px solid var(--line);background:rgba(255,255,255,.05);color:white;border-radius:3px;cursor:pointer}.empty-state{text-align:center;padding:100px 20px;color:#829a96}.empty-state h2{font-family:'Barlow Condensed';font-size:38px;color:white}
@keyframes pulse{50%{transform:scale(1.08);opacity:.65}}@keyframes shine{50%{filter:saturate(1.3) brightness(1.08)}}@keyframes sweep{to{transform:translateX(90%) rotate(20deg)}}@keyframes deal{from{opacity:0;transform:translateY(100px) rotateY(90deg) scale(.7)}to{opacity:1;transform:none}}@keyframes burst{to{transform:translate(var(--x),var(--y)) scale(0);opacity:0}}
@media(max-width:1000px){.top-center{display:none}.brand{width:auto}.sidebar{width:220px}.view{padding:28px}.hero{grid-template-columns:1fr 380px}.reveal-grid{grid-template-columns:repeat(4,1fr)}.reveal-grid .card{height:auto}.modal{overflow:auto}.reveal-head{position:sticky}}
@media(max-width:760px){body{padding-bottom:64px}.topbar{height:64px;padding:0 14px}.brand-copy{display:none}.brand-mark{width:48px}.wallet{margin-left:auto;border-left:0}.wallet small{display:none}.layout{height:calc(100vh - 128px)}.sidebar{display:none}.main-content{width:100%}.view{padding:20px 16px}.hero{display:flex;flex-direction:column;align-items:flex-start;min-height:auto}.hero-copy{padding-top:20px}.hero-copy p{font-size:12px}.hero h1{font-size:58px}.pack-stage{height:360px;min-height:360px;width:100%;order:-1}.pack{width:210px;height:300px}.pack-badge{top:55px}.pack-badge strong{font-size:42px}.pack-ball{width:110px;height:110px;bottom:48px;left:49px}.pack-shadow{width:230px}.hero-actions{width:100%;position:fixed;z-index:30;bottom:64px;left:0;padding:8px 12px;background:rgba(5,16,19,.96);backdrop-filter:blur(12px)}.hero-actions button{flex:1;height:48px}.mobile-nav{display:flex;position:fixed;z-index:40;bottom:0;left:0;right:0;height:64px;background:#07171a;border-top:1px solid var(--line);justify-content:space-around}.mobile-nav button{flex:1;border:0;background:none;color:#78908c;font-size:9px}.mobile-nav button b{display:block;font-size:16px;margin-bottom:3px}.mobile-nav button.active{color:var(--acid)}.team-grid,.card-grid,.shop-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.page-head h2{font-size:38px}.page-head .progress{width:130px}.reveal-grid{grid-template-columns:repeat(3,1fr);gap:6px}.reveal-grid .card{height:190px;padding:5px}.reveal-grid .card-name{font-size:14px}.modal-backdrop{align-items:start;padding-top:28px}.sell-row{grid-template-columns:58px 1fr 80px}.sell-row>p{display:none}}

// PANINI WORLD CUP 2026 PACK OPENING
const TEAMS=[
['Argentina','ARG','South America','#75bde8'],['Australia','AUS','Asia','#ffd54a'],['Austria','AUT','Europe','#ed2939'],['Belgium','BEL','Europe','#fdc500'],['Bolivia','BOL','South America','#7bc96f'],['Brazil','BRA','South America','#ffdc3d'],['Canada','CAN','North America','#ed1c24'],['Chile','CHI','South America','#ee3145'],['Colombia','COL','South America','#f7c948'],['Costa Rica','CRC','North America','#d64545'],['Croatia','CRO','Europe','#e63946'],['Czechia','CZE','Europe','#e8edf2'],['Denmark','DEN','Europe','#e12535'],['Ecuador','ECU','South America','#f4c430'],['Egypt','EGY','Africa','#f15b3a'],['England','ENG','Europe','#cfdaf0'],['France','FRA','Europe','#3155a7'],['Germany','GER','Europe','#dedede'],['Ghana','GHA','Africa','#f0c400'],['Hungary','HUN','Europe','#e94b46'],['Iran','IRN','Asia','#d8a44a'],['Iraq','IRQ','Asia','#55a864'],['Italy','ITA','Europe','#4b89c5'],['Ivory Coast','CIV','Africa','#ee8b42'],['Japan','JPN','Asia','#5c75b7'],['Mexico','MEX','North America','#3c9d70'],['Morocco','MAR','Africa','#cb3d43'],['Netherlands','NED','Europe','#ef7d32'],['Nigeria','NGA','Africa','#65a96a'],['Norway','NOR','Europe','#df3d46'],['Panama','PAN','North America','#ed5c5c'],['Paraguay','PAR','South America','#cf4c55'],['Peru','PER','South America','#c64a54'],['Poland','POL','Europe','#e85f71'],['Portugal','POR','Europe','#b72d45'],['Qatar','QAT','Asia','#7c2f55'],['Saudi Arabia','KSA','Asia','#49a46a'],['Scotland','SCO','Europe','#587db2'],['Senegal','SEN','Africa','#52a768'],['Serbia','SRB','Europe','#cf4654'],['South Korea','KOR','Asia','#d95454'],['Spain','ESP','Europe','#df4a47'],['Sweden','SWE','Europe','#ebc94b'],['Switzerland','SUI','Europe','#e74c4c'],['Türkiye','TUR','Europe','#d94b51'],['Ukraine','UKR','Europe','#5f95d4'],['United States','USA','North America','#587ca9'],['Uruguay','URU','South America','#72a9cf']];
const FIRST=['Lionel','Kylian','Mohamed','Vinícius','Lamine','Jude','Harry','Bukayo','Rodri','Alisson','Bruno','Neymar','Cristiano','Kevin','Antoine','Lautaro','Federico','Rafael','Julian','Gabriel','Erling','Jamal','Florian','Kai','Cole','Declan','Rúben','Achraf','Victor','Federico','Luis','Darwin','Alexis','James','Dušan','Pedri','Gavi','Xavi','Virgil','William','Theo','Martin','Jules','João','Bernardo','Álvaro','Nicola','Khvicha','Victor','Christian'];
const LAST=['Messi','Mbappé','Salah','Júnior','Yamal','Bellingham','Kane','Saka','Hernández','Becker','Fernandes','Júnior','Ronaldo','De Bruyne','Griezmann','Martínez','Valverde','Leão','Álvarez','Martinelli','Haaland','Musiala','Wirtz','Havertz','Palmer','Rice','Dias','Hakimi','Osimhen','Dimarco','Suárez','Nuñez','Sánchez','Rodriguez','Vlahović','González','Paez','Simons','van Dijk','Saliba','Hernández','Ødegaard','Koundé','Palhinha','Silva','Morata','Barella','Kvaratskhelia','Boniface','Eriksen'];
const RARITIES=[
 ['Common','1',48],['Rare','2',22],['Super Rare','4',12],['Epic','7',8],['Legendary','12',5],['Iconic','20',3],['Golden Baller','30',1.5],['Limited Edition','40',.5]
];
let state=JSON.parse(localStorage.getItem('pwc2026-save')||'null')||{money:50,cards:{}};
const cards=[];
TEAMS.forEach((t,ti)=>{for(let i=0;i<18;i++){const ri=i%FIRST.length; const name=(i<10?FIRST[(ti*3+i)%FIRST.length]:FIRST[(ti*7+i)%FIRST.length])+' '+(i<11?LAST[(ti*5+i)%LAST.length]:LAST[(ti*9+i)%LAST.length]);cards.push({id:`${t[1]}-${i}`,team:t[0],code:t[1],name,rarityIndex:i<7?0:i<11?1:i<14?2:i<16?3:i===16?4:i===17?5:0});}});
// ensure the collection has every rarity represented
for(let ti=0;ti<TEAMS.length;ti++){for(let n=0;n<3;n++){const ri=5+n;if(n===2&&ti%10===0){} cards.push({id:`${TEAMS[ti][1]}-SPECIAL-${n}`,team:TEAMS[ti][0],code:TEAMS[ti][1],name:["Golden Talent","World Stage","Limited Legend"][n]+' '+TEAMS[ti][1],rarityIndex:[6,7,5][n]});}}
const rarityName=i=>RARITIES[i][0], rarityClass=i=>RARITIES[i][0].toLowerCase().replaceAll(' ','-');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function save(){localStorage.setItem('pwc2026-save',JSON.stringify(state));updateChrome()}
function updateChrome(){ $('#balance').textContent=state.money; const vals=Object.values(state.cards); $('#topOwned').textContent=vals.reduce((a,b)=>a+b,0); const unique=vals.filter(v=>v>0).length; $('#collectionNavCount').textContent=unique; $('#albumNavCount').textContent=Math.round(unique/cards.length*100)+'%'; $('#duplicateNavCount').textContent=vals.filter(v=>v>1).reduce((a,b)=>a+b-1,0)}
function nav(view){ $$('.view').forEach(v=>v.classList.remove('active')); $('#view-'+view).classList.add('active'); $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); if(view==='home')renderHome(); if(view==='album')renderAlbum(); if(view==='collection')renderCollection(); if(view==='shop')renderShop(); if(view==='sell')renderSell(); if(view==='mycards')renderMyCards();}
function renderHome(){ $('#view-home').innerHTML=`<div class="hero"><div class="hero-copy"><div class="eyebrow">DROP OF THE SEASON · 2026</div><h1>COLLECT<br><span class="hollow">THE GAME</span></h1><p>Construiește colecția ta pentru Campionatul Mondial 2026. Deschide pachete, descoperă legende și completează cele 48 de naționale.</p><div class="hero-actions"><button class="primary-btn" id="openNormal">Deschide pachet · 5 LEI</button><button class="secondary-btn" id="gotoAlbum">Vezi albumul</button></div></div><div class="pack-stage"><div class="pack-aura"></div><div class="pack-shadow"></div><div class="pack" id="heroPack"><div class="pack-grid"></div><div class="pack-badge"><strong>WC</strong><small>2026 · SERIES 01</small></div><div class="pack-ball"></div><div class="pack-footer"><span>48 NATIONS</span><b>OFFICIAL EDITION</b></div></div></div></div>`;$('#openNormal').onclick=$('#heroPack').onclick=()=>openPack('normal');$('#gotoAlbum').onclick=()=>nav('album')}
function renderAlbum(){let html=`<div class="page-head"><div><div class="eyebrow">COLECȚIA ALBUMULUI</div><h2>Naționale · 48</h2></div><div class="progress"><div class="progress-label"><span>COMPLETARE</span><span>${uniqueTeams()} / 48</span></div><div class="progress-track"><div class="progress-fill" style="width:${uniqueTeams()/48*100}%"></div></div></div></div><div class="team-grid">`;TEAMS.forEach(t=>{const own=cards.filter(c=>c.code===t[1]).filter(c=>state.cards[c.id]>0).length;const total=cards.filter(c=>c.code===t[1]).length;html+=`<article class="team-card" data-team="${t[1]}"><div class="team-flag" style="background:linear-gradient(135deg,${t[3]},rgba(255,255,255,.12))">${t[1]}</div><h3>${t[0]}</h3><small>${own} deținute · ${Math.max(0,total-own)} lipsă</small><div class="mini-progress"><i style="width:${own/total*100}%"></i></div></article>`});html+='</div>';$('#view-album').innerHTML=html;$$('.team-card').forEach(el=>el.onclick=()=>openTeam(el.dataset.team))}
function uniqueTeams(){return TEAMS.filter(t=>cards.some(c=>c.code===t[1]&&state.cards[c.id]>0)).length}
function openTeam(code){const t=TEAMS.find(x=>x[1]===code);const teamCards=cards.filter(c=>c.code===code);const owned=teamCards.filter(c=>state.cards[c.id]>0).length;$('#view-album').innerHTML=`<div class="page-head"><div><div class="eyebrow"><span style="cursor:pointer" id="backAlbum">← ÎNAPOI</span></div><h2>${t[0]}</h2></div><div class="progress"><div class="progress-label"><span>ECHIPĂ</span><span>${owned}/${teamCards.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${owned/teamCards.length*100}%"></div></div></div></div><div class="card-grid">${teamCards.map(c=>cardHTML(c,true)).join('')}</div>`;$('#backAlbum').onclick=renderAlbum}
function cardHTML(c,lockedCheck=false){const count=state.cards[c.id]||0;if(lockedCheck&&!count)return`<div class="card locked ${rarityClass(c.rarityIndex)}"><div class="card-bg"></div></div>`;const cl=rarityClass(c.rarityIndex);return `<article class="card ${cl}"><div class="card-bg"></div><div class="rarity ${cl}">${rarityName(c.rarityIndex)}</div><div class="card-team">${c.code}</div><div class="avatar"></div><div class="card-name">${c.name}<small>${c.team}</small></div>${count?`<span class="card-count">×${count}</span>`:''}</article>`}
function renderCollection(){const owned=cards.filter(c=>state.cards[c.id]>0);let html=`<div class="page-head"><div><div class="eyebrow">MY COLLECTION</div><h2>Cartonașe</h2></div><div class="progress"><div class="progress-label"><span>UNICE</span><span>${owned.length}/${cards.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${owned.length/cards.length*100}%"></div></div></div></div><div class="card-grid">`;html+=(owned.length?owned.map(c=>cardHTML(c)).join(''):'<div class="empty-state" style="grid-column:1/-1"><h2>Colecția este goală</h2><p>Deschide primul pachet pentru a începe.</p></div>');html+='</div>';$('#view-collection').innerHTML=html}
function renderMyCards(){renderCollection();$('#view-mycards').innerHTML=$('#view-collection').innerHTML.replace('<h2>Cartonașe</h2>','<h2>Cartonașele mele</h2>')}
function renderShop(){$('#view-shop').innerHTML=`<div class="page-head"><div><div class="eyebrow">PACK STORE</div><h2>Magazin</h2></div></div><div class="shop-grid"><article class="shop-card"><div class="shop-pack">7<br><small>CARD</small></div><h3>Pachet Normal</h3><p>7 cartonașe aleatorii</p><button class="buy-btn" data-pack="normal">Cumpără · 5 LEI</button></article><article class="shop-card featured"><div class="shop-pack" style="--pack-a:#6c8c78">PREM</div><h3>Pachet Premium</h3><p>7 cartonașe · șanse mai bune</p><button class="buy-btn" data-pack="premium">Cumpără · 10 LEI</button></article><article class="shop-card special"><div class="shop-pack">WC</div><h3>Pachet Special</h3><p>7 cartonașe · șanse legende</p><button class="buy-btn" data-pack="special">Cumpără · 20 LEI</button></article></div>`;$$('[data-pack]').forEach(b=>b.onclick=()=>openPack(b.dataset.pack))}
function randomCard(pack){let roll=Math.random()*100, index;if(pack==='normal'){index=roll<55?0:roll<78?1:roll<90?2:roll<96?3:roll<98.7?4:roll<99.6?5:roll<99.92?6:7}else if(pack==='premium'){index=roll<38?0:roll<64?1:roll<79?2:roll<90?3:roll<96.5?4:roll<99?5:roll<99.8?6:7}else{index=roll<25?0:roll<48?1:roll<63?2:roll<76?3:roll<88?4:roll<96?5:roll<99.3?6:7}let pool=cards.filter(c=>c.rarityIndex===index);if(!pool.length){pool=cards.filter(c=>c.rarityIndex===Math.min(index,5))}return pool[Math.floor(Math.random()*pool.length)]}
function openPack(pack){const cost={normal:5,premium:10,special:20}[pack];if(state.money<cost){toast('Fonduri insuficiente');return}state.money-=cost;const drawn=[];for(let i=0;i<7;i++){const c=randomCard(pack);drawn.push(c);state.cards[c.id]=(state.cards[c.id]||0)+1}save();showReveal(drawn)}
function showReveal(drawn){const modal=$('#modal');modal.innerHTML=`<div class="reveal-head">PACHETUL A FOST DESCHIS</div><div class="reveal-grid">${drawn.map(cardHTML).join('')}</div><div class="modal-actions"><button class="secondary-btn" id="closeReveal">Închide</button><button class="primary-btn" id="openAgain">Deschide altul</button></div>`;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');$('#closeReveal').onclick=closeModal;$('#openAgain').onclick=()=>{closeModal();openPack('normal')};drawn.forEach(c=>{if(c.rarityIndex>=4)setTimeout(()=>burst(window.innerWidth/2,window.innerHeight/2),200)})}
function closeModal(){ $('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true')}
$('#modalBackdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal()};
function renderSell(){const duplicates=cards.filter(c=>state.cards[c.id]>1);let html=`<div class="page-head"><div><div class="eyebrow">PLAYER MARKET</div><h2>Vinde duplicate</h2></div></div>`;html+=duplicates.length?duplicates.map(c=>{const dup=state.cards[c.id]-1, price=Number(RARITIES[c.rarityIndex][1])*dup;return `<div class="sell-row"><div class="mini-card" style="background:linear-gradient(145deg,var(--c1),var(--c2)"></div><div><h3>${c.name}</h3><p>${c.team} · ${rarityName(c.rarityIndex)} · ${dup} duplicate</p></div><p><b>${RARITIES[c.rarityIndex][1]} LEI</b>/cartonaș</p><button data-sell="${c.id}">Vinde · ${price} LEI</button></div>`}).join(''):'<div class="empty-state"><h2>Nu ai duplicate</h2><p>Acest cartonaș va apărea aici după ce ai mai mult de unul.</p></div>';$('#view-sell').innerHTML=html;$$('[data-sell]').forEach(b=>b.onclick=()=>sellCard(b.dataset.sell))}
function sellCard(id){const c=cards.find(x=>x.id===id), count=state.cards[id]||0;if(count<2)return;const sellCount=count-1;state.cards[id]=1;state.money+=sellCount*Number(RARITIES[c.rarityIndex][1]);save();toast(`Ai vândut ${sellCount} cartonașe pentru ${sellCount*RARITIES[c.rarityIndex][1]} LEI`);renderSell()}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function burst(x,y){const d=document.createElement('div');d.className='burst';d.style.left=x+'px';d.style.top=y+'px';for(let i=0;i<35;i++){const p=document.createElement('i');const a=Math.random()*Math.PI*2,r=80+Math.random()*220;p.style.setProperty('--x',Math.cos(a)*r+'px');p.style.setProperty('--y',Math.sin(a)*r+'px');d.appendChild(p)}document.body.appendChild(d);setTimeout(()=>d.remove(),1300)}
$$('.nav-item').forEach(b=>b.onclick=()=>nav(b.dataset.view));$('#menuToggle').onclick=()=>$('.sidebar').classList.toggle('open');
$('#mobileNav').innerHTML=`<button class="active" data-m="home"><b>◈</b>OPEN</button><button data-m="album"><b>▤</b>ALBUM</button><button data-m="shop"><b>＋</b>SHOP</button><button data-m="sell"><b>⇧</b>SELL</button><button data-m="mycards"><b>▣</b>CARDS</button>`;$$('[data-m]').forEach(b=>b.onclick=()=>{$$('[data-m]').forEach(x=>x.classList.remove('active'));b.classList.add('active');nav(b.dataset.m)});
renderHome();save();

